-- Resolve legacy duplicate display names without changing browser credentials.
-- Fail rather than lose identities if the name pool cannot accommodate them.
CREATE TABLE nickname_reassignments (author_key TEXT PRIMARY KEY, nickname TEXT NOT NULL UNIQUE);
INSERT INTO nickname_reassignments
WITH ranked AS (
 SELECT author_key,nickname,ROW_NUMBER() OVER(PARTITION BY nickname ORDER BY rowid) AS occurrence FROM identities
), duplicates AS (
 SELECT author_key,ROW_NUMBER() OVER(ORDER BY author_key) AS position FROM ranked WHERE occurrence>1
), available AS (
 SELECT value AS nickname,ROW_NUMBER() OVER(ORDER BY value) AS position
