SELECT d.author_key,a.nickname FROM duplicates d LEFT JOIN available a USING(position);
UPDATE identities SET nickname=(SELECT nickname FROM nickname_reassignments n WHERE n.author_key=identities.author_key)
 WHERE author_key IN(SELECT author_key FROM nickname_reassignments);
UPDATE posts SET nickname=(SELECT nickname FROM nickname_reassignments n WHERE n.author_key=posts.author_key)
 WHERE author_key IN(SELECT author_key FROM nickname_reassignments);
UPDATE replies SET nickname=(SELECT nickname FROM nickname_reassignments n WHERE n.author_key=replies.author_key)
 WHERE author_key IN(SELECT author_key FROM nickname_reassignments);
UPDATE replies SET reply_to_name=(SELECT target.nickname FROM replies target WHERE target.id=replies.reply_to) WHERE reply_to IS NOT NULL;
DROP TABLE nickname_reassignments;
CREATE UNIQUE INDEX identities_unique_nickname ON identities(nickname);
